import { useState, useEffect } from 'react';
import { useApp } from '../context/AppContext';
import Avatar from '../components/shared/Avatar';
import Loader from '../components/shared/Loader';
import MemberModal from '../components/modals/MemberModal';

// ─── Medal colors for top 3 ───────────────────────────────────────────────────
const RANK_STYLES = [
  { bg: 'linear-gradient(135deg,#f59e0b22,#f59e0b08)', border: '#f59e0b55', badge: '#f59e0b', label: '🥇' },
  { bg: 'linear-gradient(135deg,#9ca3af22,#9ca3af08)', border: '#9ca3af55', badge: '#9ca3af', label: '🥈' },
  { bg: 'linear-gradient(135deg,#b45309222,#b4530908)', border: '#b4530955', badge: '#cd7c2f', label: '🥉' },
];

// ─── Generate a consistent avatar color from username ────────────────────────
const AVATAR_COLORS = ['#52c97b','#60a5fa','#f472b6','#f59e0b','#fb923c','#34d399','#a78bfa','#f87171'];
function userColor(name) {
  let h = 0;
  for (let i = 0; i < name.length; i++) h = name.charCodeAt(i) + ((h << 5) - h);
  return AVATAR_COLORS[Math.abs(h) % AVATAR_COLORS.length];
}
function userInitials(name) {
  const parts = name.trim().split(/[\s._]+/).filter(Boolean);
  if (parts.length >= 2) return (parts[0][0] + parts[1][0]).toUpperCase();
  return name.slice(0, 2).toUpperCase();
}

// ─── Single contributor card ──────────────────────────────────────────────────
function ContributorCard({ user, rank, total }) {
  const rs      = rank < 3 ? RANK_STYLES[rank] : null;
  const color   = userColor(user['USER ID']);
  const pct     = Math.round((user['Total Uploads By User'] / total) * 100 * 10) / 10;

  return (
    <div
      style={{
        background:   rs ? rs.bg : 'var(--bg3)',
        border:       `1px solid ${rs ? rs.border : 'var(--border)'}`,
        borderRadius: 14,
        padding:      '1.1rem 1.2rem',
        display:      'flex',
        alignItems:   'center',
        gap:          '1rem',
        transition:   'all .22s',
        position:     'relative',
        overflow:     'hidden',
      }}
      onMouseEnter={e => {
        e.currentTarget.style.borderColor = rs ? rs.border : 'var(--border2)';
        e.currentTarget.style.transform   = 'translateY(-2px)';
      }}
      onMouseLeave={e => {
        e.currentTarget.style.borderColor = rs ? rs.border : 'var(--border)';
        e.currentTarget.style.transform   = 'none';
      }}
    >
      {/* Rank number */}
      <div style={{
        position:   'absolute',
        top:        8,
        right:      10,
        fontSize:   '.68rem',
        color:      rs ? rs.badge : 'var(--text3)',
        fontWeight: 700,
        letterSpacing: '.04em',
      }}>
        {rs ? rs.label : `#${rank + 1}`}
      </div>

      {/* Avatar */}
      <div style={{
        width:          42,
        height:         42,
        borderRadius:   '50%',
        background:     `${color}22`,
        border:         `2px solid ${color}55`,
        display:        'flex',
        alignItems:     'center',
        justifyContent: 'center',
        fontWeight:     700,
        fontSize:       '.82rem',
        color,
        flexShrink:     0,
        letterSpacing:  '.04em',
      }}>
        {userInitials(user['USER ID'])}
      </div>

      {/* Info */}
      <div style={{ flex: 1, minWidth: 0 }}>
        <div style={{
          fontSize:     '.88rem',
          fontWeight:   600,
          color:        'var(--text)',
          whiteSpace:   'nowrap',
          overflow:     'hidden',
          textOverflow: 'ellipsis',
          marginBottom: '.3rem',
        }}>
          {user['USER ID']}
        </div>

        {/* Progress bar */}
        <div style={{
          height:       5,
          borderRadius: 3,
          background:   'var(--bg)',
          overflow:     'hidden',
          marginBottom: '.3rem',
        }}>
          <div style={{
            height:       '100%',
            width:        `${Math.min(pct * 4, 100)}%`,
            background:   rs ? rs.badge : color,
            borderRadius: 3,
            transition:   'width .6s ease',
          }} />
        </div>

        <div style={{ fontSize: '.72rem', color: 'var(--text3)' }}>
          <span style={{ color: rs ? rs.badge : color, fontWeight: 700 }}>
            {user['Total Uploads By User'].toLocaleString()}
          </span>
          {' '}uploads · {pct}% of total
        </div>
      </div>
    </div>
  );
}

// ─── Contributors Section ─────────────────────────────────────────────────────
function ContributorsSection() {
  const [contributors, setContributors] = useState([]);
  const [loading,      setLoading]      = useState(true);
  const [error,        setError]        = useState(null);
  const [showAll,      setShowAll]      = useState(false);

  useEffect(() => {
    fetch('https://wlbapi.toolforge.org/api/wlb/uploads-by-user')
      .then(r => { if (!r.ok) throw new Error(`HTTP ${r.status}`); return r.json(); })
      .then(d => {
        const sorted = (d?.data || []).sort(
          (a, b) => b['Total Uploads By User'] - a['Total Uploads By User']
        );
        setContributors(sorted);
        setLoading(false);
      })
      .catch(err => { setError(err.message); setLoading(false); });
  }, []);

  const totalUploads = contributors.reduce((s, u) => s + u['Total Uploads By User'], 0);
  const displayed    = showAll ? contributors : contributors.slice(0, 12);

  return (
    <section style={{ marginTop: '4rem' }}>
      {/* Header */}
      <div style={{ marginBottom: '2rem' }}>
        <div className="sec-eye">Community</div>
        <h2 className="sec-h">Top <em>Contributors</em></h2>
        <p className="sec-sub" style={{ marginTop: '.5rem' }}>
          Citizen scientists powering India's butterfly documentation.
          {!loading && contributors.length > 0 && (
            <span style={{ color: 'var(--green)', marginLeft: '.4rem' }}>
              {contributors.length} contributors · {totalUploads.toLocaleString()} total uploads
            </span>
          )}
        </p>
      </div>

      {/* Top 3 podium */}
      {!loading && !error && contributors.length >= 3 && (
        <div style={{
          display:             'grid',
          gridTemplateColumns: 'repeat(3, 1fr)',
          gap:                 '1rem',
          marginBottom:        '1.5rem',
        }}
          className="podium-grid"
        >
          {contributors.slice(0, 3).map((u, i) => (
            <div key={u['USER ID']} style={{
              background:   RANK_STYLES[i].bg,
              border:       `1px solid ${RANK_STYLES[i].border}`,
              borderRadius: 16,
              padding:      '1.5rem',
              textAlign:    'center',
              position:     'relative',
              order:        i === 0 ? 2 : i === 1 ? 1 : 3,   /* 2nd · 1st · 3rd */
              marginTop:    i === 0 ? 0 : i === 1 ? '1.5rem' : '1.5rem',
            }}>
              <div style={{ fontSize: '2rem', marginBottom: '.5rem' }}>{RANK_STYLES[i].label}</div>
              <div style={{
                width:          56,
                height:         56,
                borderRadius:   '50%',
                background:     `${userColor(u['USER ID'])}22`,
                border:         `2px solid ${RANK_STYLES[i].badge}`,
                display:        'flex',
                alignItems:     'center',
                justifyContent: 'center',
                fontWeight:     700,
                fontSize:       '1rem',
                color:          userColor(u['USER ID']),
                margin:         '0 auto .75rem',
              }}>
                {userInitials(u['USER ID'])}
              </div>
              <div style={{
                fontFamily:   'var(--ff)',
                fontSize:     '.95rem',
                fontWeight:   600,
                color:        'var(--text)',
                marginBottom: '.3rem',
                wordBreak:    'break-word',
              }}>
                {u['USER ID']}
              </div>
              <div style={{
                fontSize:   '1.4rem',
                fontWeight: 700,
                color:      RANK_STYLES[i].badge,
                fontFamily: 'var(--ff)',
              }}>
                {u['Total Uploads By User'].toLocaleString()}
              </div>
              <div style={{ fontSize: '.7rem', color: 'var(--text3)' }}>uploads</div>
            </div>
          ))}
        </div>
      )}

      {/* Rest of contributors grid */}
      {loading ? (
        <div style={{ textAlign: 'center', padding: '3rem' }}><Loader /></div>
      ) : error ? (
        <div style={{
          textAlign: 'center', padding: '2rem',
          background: 'var(--bg3)', borderRadius: 12,
          border: '1px solid var(--border)', color: 'var(--text3)',
        }}>
          ⚠️ Failed to load contributors: {error}
        </div>
      ) : (
        <>
          <div style={{
            display:             'grid',
            gridTemplateColumns: 'repeat(auto-fill, minmax(280px, 1fr))',
            gap:                 '.85rem',
          }}>
            {displayed.slice(3).map((u, i) => (
              <ContributorCard
                key={u['USER ID']}
                user={u}
                rank={i + 3}
                total={totalUploads}
              />
            ))}
          </div>

          {contributors.length > 12 && (
            <div style={{ textAlign: 'center', marginTop: '1.5rem' }}>
              <button
                className="btn btn-o"
                onClick={() => setShowAll(v => !v)}
              >
                {showAll
                  ? '↑ Show Less'
                  : `Show All ${contributors.length} Contributors ↓`}
              </button>
            </div>
          )}
        </>
      )}

      <style>{`
        @media(max-width: 600px) {
          .podium-grid {
            grid-template-columns: 1fr !important;
          }
          .podium-grid > div {
            order: unset !important;
            margin-top: 0 !important;
          }
        }
      `}</style>
    </section>
  );
}

// ─── TeamPage ─────────────────────────────────────────────────────────────────
export default function TeamPage() {
  const { state, dispatch } = useApp();
  const [dept, setDept]     = useState('all');
  const depts    = [...new Set(state.team.map(m => m.dept))];
  const filtered = dept === 'all' ? state.team : state.team.filter(m => m.dept === dept);

  return (
    <div style={{ padding: '7rem 1.5rem 4rem', maxWidth: 1200, margin: '0 auto' }}>

      {/* ── Core Team ──────────────────────────────────────────────────────── */}
      <div style={{ marginBottom: '2.5rem' }}>
        <div className="sec-eye">The People Behind the Wings</div>
        <h1 className="sec-h">Our <em>Team</em></h1>
        <p className="sec-sub" style={{ marginTop: '.5rem' }}>
          Scientists, researchers, and passionate naturalists. Click any card for full profile.
        </p>
      </div>

      {/* Department filter */}
      <div style={{ display: 'flex', gap: '.5rem', flexWrap: 'wrap', marginBottom: '2rem' }}>
        {['all', ...depts].map(d => (
          <button key={d} onClick={() => setDept(d)}
            style={{
              background:  dept === d ? 'rgba(82,201,123,.14)' : 'transparent',
              border:      `1px solid ${dept === d ? 'rgba(82,201,123,.48)' : 'var(--border)'}`,
              color:       dept === d ? 'var(--green)' : 'var(--text2)',
              padding:     '.38rem 1.05rem',
              borderRadius: 50,
              fontFamily:  'var(--fb)',
              fontSize:    '.8rem',
              cursor:      'pointer',
              transition:  'all .2s',
            }}>
            {d === 'all' ? 'All Departments' : d}
          </button>
        ))}
      </div>

      {state.teamLoading ? (
        <div style={{ textAlign: 'center', padding: '4rem' }}><Loader /></div>
      ) : (
        <div className="g2">
          {filtered.map(m => (
            <div key={m.id} className="card fu" style={{ padding: '1.5rem', cursor: 'pointer' }}
              onClick={() => dispatch({ type: 'SEL_MEMBER', v: m })}>
              <div style={{ display: 'flex', alignItems: 'center', gap: '1rem', marginBottom: '1.1rem' }}>
                <Avatar i={m.initials} c={m.color} />
                <div>
                  <div style={{ fontFamily: 'var(--ff)', fontSize: '1.1rem', color: 'var(--text)' }}>{m.name}</div>
                  <div style={{ fontSize: '.78rem', color: 'var(--text2)', marginBottom: '.35rem' }}>{m.role}</div>
                  <span className="tag t-green" style={{ fontSize: '.66rem' }}>{m.dept}</span>
                </div>
              </div>
              <p style={{ fontSize: '.83rem', color: 'var(--text2)', lineHeight: 1.65, marginBottom: '1rem' }}>
                {m.bio.substring(0, 128)}...
              </p>
              <div style={{ display: 'flex', gap: '1rem', paddingTop: '.85rem', borderTop: '1px solid var(--border)', marginBottom: '.75rem' }}>
                {[['📄', m.publications, 'Papers'], ['🗺️', m.fieldTrips, 'Trips'], ['🦋', m.species_described, 'Species']].map(([ic, v, l]) => (
                  <div key={l} style={{ textAlign: 'center', flex: 1 }}>
                    <div style={{ fontSize: '.75rem', color: 'var(--text3)' }}>{ic}</div>
                    <div style={{ fontFamily: 'var(--ff)', fontSize: '1.15rem', color: 'var(--green)' }}>{v}</div>
                    <div style={{ fontSize: '.68rem', color: 'var(--text3)' }}>{l}</div>
                  </div>
                ))}
              </div>
              <div style={{ display: 'flex', gap: '.4rem', flexWrap: 'wrap', justifyContent: 'space-between', alignItems: 'center' }}>
                <div style={{ display: 'flex', gap: '.35rem', flexWrap: 'wrap' }}>
                  {Object.keys(m.social).map(p => (
                    <a key={p} href={m.social[p]} target="_blank" rel="noopener noreferrer"
                      onClick={e => e.stopPropagation()}
                      style={{ padding: '.26rem .6rem', borderRadius: 50, background: 'rgba(255,255,255,.04)', border: '1px solid var(--border)', color: 'var(--text3)', textDecoration: 'none', fontFamily: 'var(--fb)', fontSize: '.68rem', transition: 'all .2s' }}
                      onMouseEnter={e => { e.currentTarget.style.color = 'var(--green)'; e.currentTarget.style.borderColor = 'var(--border2)'; }}
                      onMouseLeave={e => { e.currentTarget.style.color = 'var(--text3)'; e.currentTarget.style.borderColor = 'var(--border)'; }}>
                      {p}
                    </a>
                  ))}
                </div>
                <button className="btn-sm">Full Profile →</button>
              </div>
            </div>
          ))}
        </div>
      )}

      {/* ── Contributors from API ───────────────────────────────────────────── */}
      <ContributorsSection />

      {/* ── CTA ────────────────────────────────────────────────────────────── */}
      <div style={{ marginTop: '3rem', textAlign: 'center', background: 'var(--bg3)', border: '1px solid var(--border)', borderRadius: 20, padding: '2.5rem' }}>
        <div style={{ fontSize: '2rem', marginBottom: '.75rem' }}>🦋</div>
        <h3 style={{ fontFamily: 'var(--ff)', fontSize: '1.6rem', marginBottom: '.5rem' }}>Join Our Mission</h3>
        <p style={{ color: 'var(--text2)', fontFamily: 'var(--ff)', fontSize: '.95rem', marginBottom: '1.5rem', fontStyle: 'italic' }}>
          Researchers, naturalists, photographers, and policy advocates — all welcome.
        </p>
        <div style={{ display: 'flex', gap: '.75rem', justifyContent: 'center', flexWrap: 'wrap' }}>
          <button className="btn btn-p">Apply as Researcher</button>
          <button className="btn btn-o">Volunteer</button>
        </div>
      </div>

      {state.selectedMember && <MemberModal />}
    </div>
  );
}
